<section class="admin-welcome"><div><p class="eyebrow">GESTION UTILISATEUR</p><h1><?= htmlspecialchars($managedUser['name']) ?></h1><p>Modifiez ses accès, activez son compte ou définissez un nouveau mot de passe.</p></div><a class="btn secondary" href="/admin/utilisateurs">← Retour aux utilisateurs</a></section>
<div class="user-manager-grid"><form class="panel modern-form user-manager-form" method="post" action="/admin/utilisateurs/modifier"><input type="hidden" name="id" value="<?= (int)$managedUser['id'] ?>"><div class="panel-heading"><div><h2>Informations et accès</h2><p>Les modifications s’appliquent immédiatement.</p></div><span class="status <?= $managedUser['status']==='active'?'published':'draft' ?>"><?= $managedUser['status']==='active'?'Compte actif':'Activation en attente' ?></span></div><div class="form-row"><label class="field"><span>Nom complet *</span><input name="name" value="<?= htmlspecialchars($managedUser['name']) ?>" required></label><label class="field"><span>Email *</span><input type="email" name="email" value="<?= htmlspecialchars($managedUser['email']) ?>" required></label></div><div class="form-row"><label class="field"><span>Téléphone / identifiant *</span><input name="phone" value="<?= htmlspecialchars($managedUser['phone']??'') ?>" required></label><label class="field"><span>Rôle</span><select name="role"><option value="learner" <?= $managedUser['role']==='learner'?'selected':'' ?>>Apprenant</option><option value="instructor" <?= $managedUser['role']==='instructor'?'selected':'' ?>>Formateur</option><option value="admin" <?= $managedUser['role']==='admin'?'selected':'' ?>>Administrateur</option></select></label></div><label class="field"><span>État du compte</span><select name="status"><option value="active" <?= $managedUser['status']==='active'?'selected':'' ?>>Actif — connexion autorisée</option><option value="disabled" <?= $managedUser['status']!=='active'?'selected':'' ?>>Désactivé — connexion bloquée</option></select></label><hr><div class="security-heading"><div><h3>Réinitialiser le mot de passe</h3><p>Laissez vide pour conserver le mot de passe actuel.</p></div></div><div class="form-row"><label class="field"><span>Nouveau mot de passe</span><input type="password" name="password" minlength="8" autocomplete="new-password"></label><label class="field"><span>Confirmation</span><input type="password" name="password_confirmation" minlength="8" autocomplete="new-password"></label></div><button class="btn primary" type="submit">Enregistrer le compte</button></form><aside class="panel user-enrollments"><div class="panel-heading"><div><h2>Formations rattachées</h2><p><?= count($enrollments) ?> inscription(s)</p></div></div><?php if(!$enrollments): ?><div class="admin-empty">Aucune formation rattachée.</div><?php else: ?><?php foreach($enrollments as $enrollment): ?><article><div><strong><?= htmlspecialchars($enrollment['title']) ?></strong><small>Inscrit le <?= date('d/m/Y',strtotime($enrollment['enrolled_at'])) ?></small></div><span class="status <?= in_array($enrollment['status'],['active','completed'],true)?'published':'draft' ?>"><?= htmlspecialchars($enrollment['status']) ?></span><div class="progress-row"><div class="progress"><span style="width:<?= (int)$enrollment['progress'] ?>%"></span></div><b><?= (int)$enrollment['progress'] ?>%</b></div></article><?php endforeach ?><?php endif ?></aside></div>
<style>.user-manager-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:18px}.user-manager-form,.user-enrollments{padding:22px}.security-heading h3{margin-bottom:4px}.security-heading p{color:var(--muted);font-size:10px}.user-enrollments article{padding:14px 0;border-bottom:1px solid var(--border)}.user-enrollments article>div:first-child{display:flex;justify-content:space-between;gap:12px}.user-enrollments small{display:block;color:var(--muted);font-size:9px;margin-top:5px}.user-enrollments .progress-row{margin-top:10px}@media(max-width:900px){.user-manager-grid{grid-template-columns:1fr}}</style>
